        // 即单调队列队首保存的是max(dp[0]~dp[i-1])
        dp[i] = queue[queue_first_idx] + scores[i];

        // 保持单调队列的单调递减性，即如果后入队的dp[i] 大于 队尾元素，则队尾元素出队
